select
md5((select jsonb_agg(to_jsonb(p) order by p.oid) from pg_proc p where p.oid in ('auth.uid()'::regprocedure,'auth.jwt()'::regprocedure,'private.account_access_allowed()'::regprocedure,'private.account_deletion_barrier_key(uuid)'::regprocedure,'private.require_reauthentication_session()'::regprocedure,'public.current_user_required_document_attention()'::regprocedure))::text) as functions_hash,
md5((select jsonb_agg(to_jsonb(n) order by n.oid) from pg_namespace n where n.nspname in ('public','private','auth'))::text) as schemas_hash,
md5((select coalesce(jsonb_agg(to_jsonb(a) order by a.oid),'[]'::jsonb) from pg_default_acl a)::text) as defaults_hash,
md5((select jsonb_agg(jsonb_build_object('class',to_jsonb(c)-array['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'],'columns',(select jsonb_agg(to_jsonb(a) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0),'constraints',(select coalesce(jsonb_agg(to_jsonb(x) order by x.oid),'[]'::jsonb) from pg_constraint x where x.conrelid=c.oid),'policies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.oid),'[]'::jsonb) from pg_policy x where x.polrelid=c.oid),'triggers',(select coalesce(jsonb_agg(to_jsonb(x) order by x.oid),'[]'::jsonb) from pg_trigger x where x.tgrelid=c.oid)) order by c.oid) from pg_class c where c.oid in ('public.company_members'::regclass,'public.workers'::regclass,'public.document_requirements'::regclass,'public.worker_document_statuses'::regclass,'public.worker_private_bank_accounts'::regclass,'private.worker_document_exemptions'::regclass,'auth.users'::regclass,'auth.sessions'::regclass,'private.account_deletion_access_restrictions'::regclass))::text) as relations_hash;
